<script setup lang="ts">
import {ref,watch,onMounted} from 'vue';import {campaignApi} from '../campaign-api';import type {WorkTab} from '../stores';import Modal from './Modal.vue';import {reorderMarketingImages,marketingUploadError,MAX_MARKETING_IMAGES} from '../../../lib/workspace/campaign-rules';
const props=defineProps<{department:'marketing'|'merchandise';campaign:any;canEdit:boolean;tab:WorkTab}>();
const dragFrom=ref<number|null>(null),dragOver=ref<number|null>(null);
function moveImage(from:number,to:number){form.value=reorderMarketingImages(form.value,from,to);}
function dropImage(to:number){if(dragFrom.value!==null)moveImage(dragFrom.value,to);dragFrom.value=null;dragOver.value=null;}
const form=ref<any>({}),baseline=ref(''),loading=ref(true),error=ref(''),message=ref(''),discard=ref(false);
const array=(v:any):string[]=>{if(Array.isArray(v))return v;if(!v)return [];try{const r=JSON.parse(v);return Array.isArray(r)?r:[v];}catch{return [v];}};
const safe=(v:string)=>/^(https:\/\/|data:(image\/(png|jpeg|webp|gif)|application\/[\w.+-]+);base64,)/i.test(v||'')?v:'';
watch(form,()=>props.tab.dirty=!!baseline.value&&JSON.stringify(form.value)!==baseline.value,{deep:true,flush:'sync'});props.tab.submitOnly=true;
async function load(){loading.value=true;error.value='';try{const d=(await campaignApi('departments',{campaign_id:props.campaign.id})).data||{};form.value=props.department==='marketing'?{marketing_content:d.marketing_content||'',marketing_rules:d.marketing_rules||'',marketing_image_names:array(d.marketing_image_names),marketing_image_paths:array(d.marketing_image_paths),marketing_image_urls:array(d.marketing_image_urls),marketing_image_name:d.marketing_image_name,marketing_image_data:d.marketing_image_data}:{merchandise_supply_content:d.merchandise_supply_content||'',merchandise_gift_rules_name:d.merchandise_gift_rules_name,merchandise_gift_rules_data:d.merchandise_gift_rules_data,merchandise_allocation_file_name:d.merchandise_allocation_file_name,merchandise_allocation_file_data:d.merchandise_allocation_file_data};baseline.value=JSON.stringify(form.value);props.tab.dirty=false;}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
async function upload(e:Event,key=''){const input=e.target as HTMLInputElement,files=Array.from(input.files||[]);input.value='';if(!files.length)return;props.tab.busy=true;error.value='';try{
 if(props.department==='marketing'){const bad=marketingUploadError(form.value.marketing_image_urls.length,files);if(bad)throw Error(bad);const body=new FormData();body.append('campaign_id',props.campaign.id);body.append('department','marketing');files.forEach(f=>body.append('files',f));const r=(await campaignApi('assets',{},'POST',body)).data;for(const k of ['names','paths','urls'])form.value['marketing_image_'+k].push(...r[k]);}
 else{if(files.some(f=>f.size>5*1024*1024))throw Error('每個檔案須小於 5MB');const f=files[0];if(key==='merchandise_gift_rules'&&!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error('請選擇 PNG、JPEG 或 WebP 圖片');if(key==='merchandise_allocation_file'&&!/\.(xlsx|xls)$/i.test(f.name))throw Error('請選擇 Excel 檔案');const data=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(f);});form.value[key+'_name']=f.name;form.value[key+'_data']=data;}
 }catch(e){error.value=(e as Error).message;}finally{props.tab.busy=false;}}
async function save(){props.tab.busy=true;error.value='';try{await campaignApi('departments',{},'POST',{...form.value,campaign_id:props.campaign.id,department:props.department});baseline.value=JSON.stringify(form.value);props.tab.dirty=false;message.value='已儲存並發布'+(props.department==='marketing'?'行銷':'商品')+'部內容';}catch(e){error.value=(e as Error).message;}finally{props.tab.busy=false;}}
onMounted(load);
</script>
<template><div class="toolbar"><h2>{{department==='marketing'?'行銷部':'商品部'}}規劃</h2><button :disabled="tab.busy" @click="tab.dirty?discard=true:load()">重新載入</button></div><p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p><p v-if="loading">讀取中…</p><form v-else @submit.prevent="save"><fieldset :disabled="!canEdit||tab.busy||!baseline"><template v-if="department==='marketing'"><label>活動內容<textarea v-model="form.marketing_content" rows="6"/></label><label>活動規則<textarea v-model="form.marketing_rules" rows="6"/></label><label>上傳活動圖片（最多 {{MAX_MARKETING_IMAGES}} 張，每張最多 5MB，目前 {{form.marketing_image_urls.length}} 張）<input type="file" multiple accept="image/png,image/jpeg,image/webp" :disabled="form.marketing_image_urls.length>=MAX_MARKETING_IMAGES" @change="upload($event)"></label><p v-if="form.marketing_image_urls.length>1" class="hint">可拖曳圖片調整順序，順序會依序顯示給店長與督導；手機可用「前移／後移」。</p><div class="assets"><div v-for="(url,i) in form.marketing_image_urls" :key="i" class="image-card" :class="{over:dragOver===i&&dragFrom!==i}" :draggable="canEdit" @dragstart="dragFrom=i" @dragover.prevent="dragOver=i" @dragleave="dragOver=null" @drop.prevent="dropImage(i)" @dragend="dragFrom=null;dragOver=null"><strong>第 {{i+1}} 張</strong><a :href="safe(url)" target="_blank" rel="noopener noreferrer"><img :src="safe(url)" :alt="form.marketing_image_names[i]"></a><span>{{form.marketing_image_names[i]}}</span><div class="order"><button type="button" :disabled="i===0" @click="moveImage(i,i-1)">前移</button><button type="button" :disabled="i===form.marketing_image_urls.length-1" @click="moveImage(i,i+1)">後移</button></div><button type="button" @click="['names','paths','urls'].forEach(k=>form['marketing_image_'+k].splice(i,1))">移除圖片</button></div><div v-if="safe(form.marketing_image_data)"><img :src="safe(form.marketing_image_data)" :alt="form.marketing_image_name||'活動圖片'"><button type="button" @click="form.marketing_image_data=null;form.marketing_image_name=null">移除原圖片</button></div></div></template>
<template v-else><label>滿額贈規則圖表<input type="file" accept="image/png,image/jpeg,image/webp" @change="upload($event,'merchandise_gift_rules')"></label><div v-if="safe(form.merchandise_gift_rules_data)" class="asset"><a :href="safe(form.merchandise_gift_rules_data)" :download="form.merchandise_gift_rules_name"><img :src="safe(form.merchandise_gift_rules_data)" alt="滿額贈規則圖表">下載 {{form.merchandise_gift_rules_name}}</a><button type="button" @click="form.merchandise_gift_rules_data=null;form.merchandise_gift_rules_name=null">移除圖表</button></div><label>商品供應說明<textarea v-model="form.merchandise_supply_content" rows="6"/></label><label>活動百貨配量 Excel<input type="file" accept=".xlsx,.xls" @change="upload($event,'merchandise_allocation_file')"></label><div v-if="safe(form.merchandise_allocation_file_data)"><a :href="safe(form.merchandise_allocation_file_data)" :download="form.merchandise_allocation_file_name">下載 {{form.merchandise_allocation_file_name}}</a><button type="button" @click="form.merchandise_allocation_file_data=null;form.merchandise_allocation_file_name=null">移除檔案</button></div></template><div class="dialog-actions"><button v-if="canEdit" class="primary" :disabled="!tab.dirty||tab.busy">{{tab.busy?'處理中…':'儲存並發布'}}</button><p v-else>目前僅可查看。</p></div></fieldset></form>
<Modal v-if="discard" title="放棄修改並重新載入？" @cancel="discard=false"><p>目前未儲存的部門內容將被放棄。</p><div class="dialog-actions"><button @click="discard=false">繼續編輯</button><button class="danger" @click="discard=false;load()">放棄修改</button></div></Modal>
</template>
<style scoped>.image-card{cursor:grab;border:1px dashed transparent;padding:6px}.image-card.over{border-color:var(--primary)}.order{display:flex;gap:6px}.hint{color:var(--muted);font-size:13px}.toolbar{display:flex;align-items:center;justify-content:space-between}h2{font-size:18px}fieldset{border:0;padding:0;min-width:0}label{display:grid;gap:8px;margin:18px 0}textarea{width:100%}.assets{display:flex;flex-wrap:wrap;gap:20px}.assets>div{max-width:240px;display:grid;gap:8px}img{display:block;max-width:100%;max-height:300px;object-fit:contain}.asset{max-width:600px}a{color:var(--primary);text-decoration:underline}input{max-width:100%}</style>
